def main():
 p=argparse.ArgumentParser();p.add_argument('--output',type=Path,required=True);p.add_argument('--budget',action='store_true');a=p.parse_args();root=a.output;prefix='current_probe_budget' if a.budget else 'current_probe';out=root/(prefix+'_quality');plan=json.loads((out/'plan.json').read_text());done=json.loads((out/'completion.json').read_text());selection=json.loads((root/(prefix+'_selection.json')).read_text());assert done['complete'];assert len(done['runs'])==18
 for path,sha in plan['source_sha256'].items():assert hashlib.sha256((ROOT/path).read_bytes()).hexdigest()==sha,path
 old=json.loads((BASE/'summary.json').read_text());previous=json.loads((root/'summary.json').read_text());rows=[];layers=[];audits=[];macros=[]
 name=selection['candidates'][0]['name'];c=selection['candidates'][0];cfg=json.loads((ROOT/c['config']).read_text());assert hashlib.sha256((ROOT/c['config']).read_bytes()).hexdigest()==c['config_sha256']
 for ds,scenes in plan['datasets'].items():
  for scene in scenes:
   folder=out/'runs'/name/ds/scene;r=json.loads((folder/'result.json').read_text());ref=json.loads((BASE/'runs'/ds/scene/'history_A_special5_cluster12_fast/result.json').read_text());assert r['quality']['complete'] and r['input']==ref['input'] and r['quality_protocol']==ref['quality_protocol'];assert r['input']['checkpoint_sha256']==selection.get('checkpoint_sha256','b08a43baa2db1aad9718e71e098831b8ad32f6f6826c802e9eb714aa34420969')
   for key,value in cfg.items():assert r['config'][key]==value,key
   t=r['timing'];assert t['warmup']==1 and t['repeats']==3 and t['median_seconds']==statistics.median(s['seconds'] for s in t['samples'])
   m=json.loads((out/'monitors'/f'{name}_{ds}_{scene}.json').read_text());assert m['returncode']==0 and not m['same_gpu_overlap_detected'] and m['max_simultaneous_gpu_applications']==1
   q=r['quality']['values'];assert abs(q['cd']-(q['acc']+q['comp'])/2)<1e-9
   row=dict(dataset=ds,scene=scene,method=name,frames=r['frames'],**q,seconds=t['median_seconds'],reference_batch_seconds=ref['timing']['median_seconds'],reference_batch_speedup=ref['timing']['median_seconds']/t['median_seconds'],warm_peak_allocated_gib=max(s['peak_allocated_gib'] for s in t['samples']),warm_peak_reserved_gib=max(s['peak_reserved_gib'] for s in t['samples']),cold_seconds=t['cold_samples'][0]['seconds'],including_cold_peak_allocated_gib=max(s['peak_allocated_gib'] for s in t['samples']+t['cold_samples']),speedup_vs_dense=None,speedup_reason='No paired Dense forward;unchanged controls not rerun');rows.append(row)
   lr=json.loads((folder/'layers.json').read_text());assert len(lr)==24
   shape=r['input']['shape'];np=r['frames']*(shape[-2]//14)*(shape[-1]//14);n=np+r['frames']*5
   for v in lr:
    assert v['fine_clusters']==math.floor(cfg['cluster_fraction']*np) and v['dense_special_query_count']==r['frames']*5
    assert v['current_probability_probes']==cfg['current_probability_probes'] and v['current_probe_qk_per_head']==v['query_groups']*cfg['current_probability_probes']*(n+np)
    # Count both observation passes and repeated special-query work. Main
